<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getSelectContext } from './select-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; ref?: HTMLDivElement | null; } let { children, ref = $bindable(null), ...rest }: Props = $props(); const select = getSelectContext();</script>
<div bind:this={ref} {...rest} id={select.listId} role="listbox" aria-labelledby={select.labelId} aria-activedescendant={select.highlighted ? `${select.listId}-${select.highlighted.replace(/[^\w-]/g, '_')}` : undefined}>{@render children?.()}</div>
